import java.text.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        Locale id = Locale.of("id", "ID");
        System.out.println("Kode: " + id.toLanguageTag());
        System.out.println("Nama bahasa: " + id.getDisplayLanguage(id));
        System.out.println("Nama negara: " + id.getDisplayCountry(id));
        Locale jp = Locale.forLanguageTag("ja-JP");
        System.out.println("Jepang dalam bahasa Indonesia: " + jp.getDisplayName(id));
        for (Locale l : List.of(id, jp, Locale.US)) {
            System.out.println(l.toLanguageTag() + " -> " + NumberFormat.getInstance(l).format(1234567.5));
        }
    }
}

import java.text.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        Locale id = Locale.of("id", "ID");
        Scanner in = new Scanner(System.in);
        while (in.hasNextLine()) {
            Locale l = Locale.forLanguageTag(in.nextLine().trim());
            System.out.println(l.toLanguageTag() + ": " + l.getDisplayName(id) + " | " + NumberFormat.getInstance(l).format(1234567.5));
        }
    }
}

