import java.text.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        Scanner in = new Scanner(System.in);
        while (in.hasNextLine()) {
            Locale l = Locale.forLanguageTag(in.nextLine().trim());
            System.out.println(l.toLanguageTag() + ": " + l.getDisplayLanguage(l) + " (" + l.getDisplayCountry(l) + ")");
        }
    }
}
